'use strict';
(function(){
const defaultBytes=628125;let sourceBytes=defaultBytes,dialog=null,token=0,timer=0,ready=null;
function bytes(n){if(!Number.isFinite(n)||n<0)return 'неизвестно';if(n<1024)return n+' Б';if(n<1048576)return (n/1024).toLocaleString('ru-RU',{maximumFractionDigits:1})+' КБ';return (n/1048576).toLocaleString('ru-RU',{maximumFractionDigits:2})+' МБ'}
const beforeSource=applySource;applySource=function(image,...args){const value=beforeSource(image,...args);sourceBytes=image.fragmentSourceBytes??(args[0]==='CLUB ENDURO LENINGRADSKAYA'?defaultBytes:null);if(dialog?.open)schedule();return value};
const beforeLoad=loadImg;loadImg=async function(src){const image=await beforeLoad(src);if(src==='assets/enduro-logo.png')image.fragmentSourceBytes=defaultBytes;else if(/^(blob:|data:)/.test(src))try{image.fragmentSourceBytes=(await(await fetch(src)).blob()).size}catch{}return image};
for(const id of ['file','projectFile']){const input=$(id),handler=input.onchange;input.onchange=async function(e){const file=e.target.files[0],previous=base;await handler.call(this,e);if(file&&base!==previous)sourceBytes=file.size}}
function project(){return new Blob([JSON.stringify({version:1,name:$('filename').textContent,base:base.toDataURL(),visible:$('baseVisible').checked,pending,layers:layers.map(serializeLayer),sourceBytes})],{type:'application/json'})}
$('save').onclick=()=>download(project(),'fragment-project.json');
function alpha(){const a=bc().getImageData(0,0,base.width,base.height).data;for(let i=3;i<a.length;i+=4)if(a[i]<255)return true;return false}
function ensure(){if(dialog)return;dialog=document.createElement('dialog');dialog.className='export-dialog';dialog.setAttribute('aria-labelledby','exportHeading');dialog.innerHTML='<h2 id="exportHeading">Сохранить</h2><div class="export-grid"><label>Формат<select id="exportFormat"><option value="png">PNG</option><option value="jpeg">JPEG</option><option value="webp">WebP</option><option value="json">Проект JSON</option></select></label><div class="export-source">Исходный файл<strong id="exportOriginal"></strong></div><label id="exportScaleField">Масштаб экспорта: <span id="exportScaleValue">100%</span><span id="exportDimensions"></span><input id="exportScale" aria-label="Масштаб экспорта" type="range" min="10" max="100" value="100"></label><label id="exportQualityField">Качество: <span id="exportQualityValue">90%</span><input id="exportQuality" aria-label="Качество сжатия" type="range" min="10" max="100" value="90"></label></div><label id="exportTransparencyField" class="export-transparency"><input type="checkbox" id="exportTransparent"> Прозрачный фон</label><p id="exportResult" role="status" aria-live="polite"></p><div class="export-actions"><button id="cancelExport">Отмена</button><button id="confirmExport" class="primary">Сохранить файл</button></div>';document.body.append(dialog);
 $('cancelExport').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{clearTimeout(timer);token++;ready=null});
 $('exportFormat').onchange=()=>{fields();schedule()};for(const id of ['exportScale','exportQuality'])$(id).oninput=schedule;$('exportTransparent').oninput=()=>{dialog.alphaChoice=$('exportTransparent').checked;schedule()};
 $('confirmExport').onclick=()=>{if(!ready)return;const output=ready;download(output.blob,output.name);dialog.close();toast('Файл сохранён')};}
function fields(){const format=$('exportFormat').value,json=format==='json';$('exportScaleField').hidden=json;$('exportQualityField').hidden=!['jpeg','webp'].includes(format);$('exportTransparencyField').hidden=json;$('exportTransparent').disabled=format==='jpeg'||(!layers.length&&!dialog.hasAlpha);$('exportTransparent').checked=!json&&format!=='jpeg'&&dialog.alphaChoice;$('exportTransparencyField').dataset.tooltip=format==='jpeg'?'JPEG сохраняется на белом фоне.':!layers.length&&!dialog.hasAlpha?'Сначала отделите объекты, чтобы убрать фон.':'Сохранить объекты без исходного фона.'}
function schedule(){if(!dialog?.open)return;clearTimeout(timer);const request=++token;ready=null;$('confirmExport').disabled=true;$('exportScaleValue').textContent=$('exportScale').value+'%';const ratio=Number($('exportScale').value)/100;$('exportDimensions').textContent=' · '+Math.max(1,Math.round(base.width*ratio))+' × '+Math.max(1,Math.round(base.height*ratio))+' пикс.';$('exportQualityValue').textContent=$('exportQuality').value+'%';$('exportResult').textContent='Результат: считаем…';timer=setTimeout(()=>encode(request),160)}
async function encode(request){try{const format=$('exportFormat').value;let blob,name,dimensions='';if(format==='json'){blob=project();name='fragment-project.json'}else{const ratio=Number($('exportScale').value)/100,w=Math.max(1,Math.round(base.width*ratio)),h=Math.max(1,Math.round(base.height*ratio)),image=off(w,h),c=image.getContext('2d'),transparent=format!=='jpeg'&&!$('exportTransparent').disabled&&$('exportTransparent').checked;c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';if(!transparent){c.fillStyle='#fff';c.fillRect(0,0,w,h)}c.scale(w/base.width,h/base.height);if($('baseVisible').checked&&(!transparent||!layers.length))c.drawImage(base,0,0);layers.forEach(layer=>drawLayer(c,layer));const mime='image/'+format;blob=await new Promise(resolve=>image.toBlob(resolve,mime,Number($('exportQuality').value)/100));if(!blob||blob.type!==mime)throw Error('Формат недоступен. Выберите PNG.');name='fragment-logo.'+(format==='jpeg'?'jpg':format);dimensions=' · '+w+' × '+h}
 if(request!==token||!dialog.open)return;ready={blob,name};$('exportResult').textContent='Результат: '+bytes(blob.size)+dimensions;$('confirmExport').disabled=false;
 }catch(error){if(request!==token)return;$('exportResult').textContent=globalThis.FragmentErrors?.report(error,'Не удалось подготовить файл.')||'Не удалось подготовить файл.'}}
$('export').onclick=()=>{ensure();$('exportOriginal').textContent=bytes(sourceBytes);dialog.hasAlpha=alpha();dialog.alphaChoice=!$('baseVisible').checked||(!layers.length&&dialog.hasAlpha);fields();if(!dialog.open)dialog.showModal();$('exportFormat').focus();schedule()};
window.FragmentExport={sourceBytes:()=>sourceBytes,setSourceBytes:value=>{sourceBytes=Number.isFinite(value)?value:null},preview:()=>ready?{size:ready.blob.size,name:ready.name,type:ready.blob.type}:null};
})();
